from z3 import *

solver = Optimize()

# Dice: 5 dice, each with 6 faces
D = [[Int(f'D_{i}_{j}') for j in range(6)] for i in range(5)]

# Constraints: values in 0..11, sorted
for i in range(5):
    for j in range(6):
        solver.add(D[i][j] >= 0, D[i][j] <= 11)
    for j in range(5):
        solver.add(D[i][j] <= D[i][j+1])

# Cyclic intransitivity: D[i] beats D[(i+1)%5] with > 18 wins
for i in range(5):
    next_i = (i + 1) % 5
    wins = 0
    for a in range(6):
        for b in range(6):
            # We can use If to count wins
            wins += If(D[i][a] > D[next_i][b], 1, 0)
    solver.add(wins >= 19)

# Try to find a solution
if solver.check() == sat:
    m = solver.model()
    result = []
    for i in range(5):
        die_faces = []
        for j in range(6):
            die_faces.append(m[D[i][j]].as_long())
        result.extend(die_faces)
    print("SAT")
    print(result)
else:
    print("UNSAT")
